1	/**
2	 * 多签钱包策略引擎。
3	 *
4	 * 在阈值策略、签名收集、重放防护、FIFO 执行队列、策略变更任务与任务取消之上，新增
5	 * “原子批量普通交易”：当前所有者以阈值签名（safe-wallet/tx-batch/v1 域，绑定钱包标识、
6	 * nonce、截止时间与按顺序编码的全部调用）提交一个有序调用列表（1..64 项）。
7	 * 批量任务只入队一个队列任务、只消费一个 nonce；执行时整批成功产生一个 transfer-batch
8	 * 回执（不产生部分执行回执），失败则整批不生效。批量任务沿用同一 FIFO 队列、取消语义与
9	 * 终态幂等；单笔交易 / 策略变更 / 取消签名均不能授权批量交易。
10	 *
11	 * 在此之上新增“普通交易分阶段审批”：createTransactionApproval 登记交易（不消费 nonce、
12	 * 不建任务），addApprovalSignature 逐个收集当前所有者签名（safe-wallet/tx-approval/v1 域，
13	 * 绑定创建时策略版本与完整交易字段），达到创建时确认数后由 submitApprovedTransaction 按
14	 * 既有 safe-wallet/tx/v1 摘要入队并只消费创建时 nonce。审批与直接提交的签名摘要互不通用。
15	 *
16	 * 再新增“策略变更分阶段审批”：createPolicyApproval 登记一次目标策略变更（绑定版本、nonce、
17	 * deadline、新所有者顺序与新确认数，不消费 nonce、不建任务、不改策略），
18	 * addPolicyApprovalSignature 逐个收集当前所有者签名（safe-wallet/policy-change-approval/v1
19	 * 域），达到创建时确认数后由 submitApprovedPolicyChange 按既有 safe-wallet/policy-change/v1
20	 * 摘要入队一个 policy-change 任务并只消费创建时 nonce。同一 nonce 可登记多个候选审批，
21	 * 登记/加签均不改策略、不耗 nonce、不动队列；提交后执行时若版本已漂移，仍按既有
22	 * PolicyConflict 失败终态处理，不改策略。
23	 */
24	
25	import {
26	  type Address,
27	  ZERO_ADDRESS,
28	  isZeroAddress,
29	  normalizeAddress,
30	  recoverAddress,
31	} from './crypto.ts';
32	import {
33	  hashCancellation,
34	  hashPolicyChange,
35	  hashPolicyApproval,
36	  hashTransaction,
37	  hashTransactionApproval,
38	  hashTransactionBatch,
39	  type PolicyApprovalRequest,
40	  type PolicyChangeRequest,
41	  type TransactionApprovalRequest,
42	  type TransactionBatchRequest,
43	  type TransactionRequest,
44	} from './encoding.ts';
45	import {
46	  ApprovalAlreadySubmittedError,
47	  ApprovalExpiredError,
48	  ApprovalNonceConflictError,
49	  ApprovalNotFoundError,
50	  ApprovalPolicyConflictError,
51	  ApprovalThresholdNotMetError,
52	  DuplicateApprovalSignatureError,
53	  InvalidApprovalSignatureError,
54	  InvalidCancellation,
55	  InvalidPolicyChange,
56	  InvalidTransaction,
57	  InvalidTransactionBatch,
58	  NonceAlreadyUsedError,
59	  RequestExpired,
60	  PolicyConflict,
61	  InvalidQueueStateError,
62	  TaskCancellationConflict,
63	  TaskNotFoundError,
64	} from './errors.ts';
65	import { ExecutionQueue, type QueueTask } from './queue.ts';
66	import { createHash } from 'node:crypto';
67	
68	// ---------- 任务载荷 ----------
69	
70	export type WalletTaskPayload =
71	  | {
72	      kind: 'transaction';
73	      deadline: bigint;
74	      to: Address;
75	      value: bigint;
76	      data: Uint8Array;
77	    }
78	  | {
79	      kind: 'transaction-batch';
80	      deadline: bigint;
81	      /** 有序调用；顺序即执行顺序，执行回执按同一顺序给出 */
82	      calls: BatchCall[];
83	    }
84	  | {
85	      kind: 'policy-change';
86	      deadline: bigint;
87	      /** 提交时绑定的策略版本；执行时必须仍等于当前版本 */
88	      version: bigint;
89	      newOwners: Address[];
90	      newConfirmations: bigint;
91	    };
92	
93	/** 批量任务内的单次调用（规范化后的收款地址、原金额、原始 data 副本） */
94	export interface BatchCall {
95	  to: Address;
96	  value: bigint;
97	  data: Uint8Array;
98	}
99	
100	export type WalletTask = QueueTask<WalletTaskPayload>;
101	
102	export interface PolicyState {
103	  owners: Address[];
104	  confirmations: bigint;
105	  version: bigint;
106	}
107	
108	export interface WalletOptions {
109	  id: string;
110	  owners: Address[];
111	  confirmations: bigint | number;
112	  /** 注入时钟，返回 Unix 秒；默认取系统时间 */
113	  now?: () => bigint;
114	}
115	
116	export interface TransactionSubmission {
117	  nonce: bigint | number;
118	  deadline: bigint | number;
119	  to: string;
120	  value: bigint | number;
121	  data?: Uint8Array;
122	}
123	
124	export interface PolicyChangeSubmission {
125	  version: bigint | number;
126	  nonce: bigint | number;
127	  deadline: bigint | number;
128	  newOwners: string[];
129	  newConfirmations: bigint | number;
130	}
131	
132	export interface CancellationSubmission {
133	  /** 目标任务 id（队列快照中的任务标识） */
134	  taskId: string;
135	  nonce: bigint | number;
136	  deadline: bigint | number;
137	}
138	
139	/** 批量提交中的单次调用（原始输入；地址在校验时规范化） */
140	export interface BatchCallSubmission {
141	  to: string;
142	  value: bigint | number;
143	  /** 必含的调用数据（允许零长度）；必须是 Uint8Array */
144	  data: Uint8Array;
145	}
146	
147	export interface BatchTransactionSubmission {
148	  nonce: bigint | number;
149	  deadline: bigint | number;
150	  /** 有序调用列表：非空且最多 MAX_BATCH_CALLS 项，顺序参与签名且不得改变 */
151	  calls: readonly BatchCallSubmission[];
152	}
153	
154	/** 批量交易调用数量上限（含） */
155	export const MAX_BATCH_CALLS = 64;
156	
157	// ---------- 普通交易分阶段审批 ----------
158	
159	/** 审批生命周期：collecting → ready → submitted；expired / conflicted 为查询派生状态 */
160	export type ApprovalStatus = 'collecting' | 'ready' | 'expired' | 'conflicted' | 'submitted';
161	
162	/** 审批的公开快照（创建 / 加签 / 查询时返回） */
163	export interface TransactionApproval {
164	  /** 审批标识（由创建序号与审批摘要派生，引擎内唯一） */
165	  id: string;
166	  /** 审批签名摘要（hex，safe-wallet/tx-approval/v1 域） */
167	  digest: string;
168	  /** 创建时绑定的策略版本 */
169	  version: bigint;
170	  /** 创建时绑定的确认数（阈值） */
171	  confirmations: bigint;
172	  /** 已收集签名者（按加签顺序，去重） */
173	  signers: Address[];
174	  status: ApprovalStatus;
175	}
176	
177	/** 审批的内部记录：完整交易字段 + 签名收集状态 */
178	interface ApprovalRecord {
179	  id: string;
180	  digest: Buffer;
181	  version: bigint;
182	  confirmations: bigint;
183	  nonce: bigint;
184	  deadline: bigint;
185	  to: Address;
186	  value: bigint;
187	  data: Buffer;
188	  /** 按加签顺序的签名者（与 signatures 的键一一对应） */
189	  signers: Address[];
190	  signatures: Map<Address, Buffer>;
191	  submitted: boolean;
192	}
193	
194	// ---------- 策略变更分阶段审批 ----------
195	
196	/** 策略变更审批的公开快照（创建 / 加签 / 查询时返回） */
197	export interface PolicyApproval {
198	  /** 审批标识（由创建序号与审批摘要派生，引擎内唯一） */
199	  id: string;
200	  /** 审批签名摘要（hex，safe-wallet/policy-change-approval/v1 域） */
201	  digest: string;
202	  /** 创建时绑定的策略版本 */
203	  version: bigint;
204	  /** 创建时绑定的确认数（阈值） */
205	  confirmations: bigint;
206	  /** 创建时绑定的 nonce（提交时才消费） */
207	  nonce: bigint;
208	  deadline: bigint;
209	  /** 目标新所有者（按创建时给定顺序；顺序参与签名） */
210	  newOwners: Address[];
211	  newConfirmations: bigint;
212	  /** 已收集签名者（按加签顺序，去重） */
213	  signers: Address[];
214	  status: ApprovalStatus;
215	}
216	
217	/** 策略变更审批的内部记录：目标策略字段 + 版本/nonce 绑定 + 签名收集状态 */
218	interface PolicyApprovalRecord {
219	  id: string;
220	  digest: Buffer;
221	  version: bigint;
222	  confirmations: bigint;
223	  nonce: bigint;
224	  deadline: bigint;
225	  newOwners: Address[];
226	  newConfirmations: bigint;
227	  /** 按加签顺序的签名者（与 signatures 的键一一对应） */
228	  signers: Address[];
229	  signatures: Map<Address, Buffer>;
230	  submitted: boolean;
231	}
232	
233	function isNonNegativeInteger(n: bigint, maxBits = 256): boolean {
234	  return n >= 0n && n < 2n ** BigInt(maxBits);
235	}
236	
237	/** 安全标量转换：非法输入（undefined / 字符串等）归一为指定的 Invalid* 错误 */
238	function toBigInt(value: unknown, Invalid: new (msg: string) => Error, field: string): bigint {
239	  if (typeof value === 'bigint') return value;
240	  if (typeof value === 'number' && Number.isSafeInteger(value)) return BigInt(value);
241	  if (typeof value === 'string' && /^\d+$/.test(value.trim())) return BigInt(value.trim());
242	  throw new Invalid(`field "${field}" must be a non-negative integer`);
243	}
244	
245	export class MultiSigWallet {
246	  readonly id: string;
247	  private readonly now: () => bigint;
248	
249	  private owners: Address[];
250	  private readonly ownerSet: Set<Address>;
251	  private confirmations: bigint;
252	  private version: bigint;
253	
254	  /** 下一个期望 nonce（严格递增，顺序提交） */
255	  private nextNonce = 0n;
256	  /** 已消费 nonce（入队即消费；失败终态也不释放） */
257	  private readonly usedNonces = new Set<bigint>();
258	
259	  /** 分阶段审批记录（按创建顺序）；创建不消费 nonce，提交时才消费 */
260	  private readonly approvals = new Map<string, ApprovalRecord>();
261	  private approvalSeq = 0;
262	
263	  /** 策略变更分阶段审批记录（按创建顺序）；与普通交易审批各自独立编号、互不影响 */
264	  private readonly policyApprovals = new Map<string, PolicyApprovalRecord>();
265	  private policyApprovalSeq = 0;
266	
267	  readonly queue: ExecutionQueue<WalletTaskPayload>;
268	
269	  constructor(opts: WalletOptions) {
270	    const owners = normalizeOwnerList(opts.owners);
271	    const confirmations = BigInt(opts.confirmations);
272	    if (confirmations <= 0n || confirmations > BigInt(owners.length)) {
273	      throw new InvalidPolicyChange(
274	        `initial confirmations must be within 1..owners (${owners.length}), got ${confirmations}`,
275	      );
276	    }
277	    this.id = opts.id;
278	    this.now = opts.now ?? (() => BigInt(Math.floor(Date.now() / 1000)));
279	    this.owners = owners;
280	    this.ownerSet = new Set(owners);
281	    this.confirmations = confirmations;
282	    this.version = 1n;
283	    this.queue = new ExecutionQueue((task) => this.applyTask(task));
284	  }
285	
286	  // ---------- 只读状态 ----------
287	
288	  get policy(): PolicyState {
289	    return { owners: [...this.owners], confirmations: this.confirmations, version: this.version };
290	  }
291	
292	  get policyVersion(): bigint {
293	    return this.version;
294	  }
295	
296	  get currentOwners(): Address[] {
297	    return [...this.owners];
298	  }
299	
300	  get requiredConfirmations(): bigint {
301	    return this.confirmations;
302	  }
303	
304	  get expectedNonce(): bigint {
305	    return this.nextNonce;
306	  }
307	
308	  isOwner(address: string): boolean {
309	    const a = normalizeAddress(address);
310	    return a !== null && this.ownerSet.has(a);
311	  }
312	
313	  isNonceUsed(nonce: bigint | number): boolean {
314	    return this.usedNonces.has(BigInt(nonce));
315	  }
316	
317	  get tasks(): readonly WalletTask[] {
318	    return this.queue.listTasks();
319	  }
320	
321	  // ---------- 普通交易提交（行为与既有流程一致，载荷不含策略版本） ----------
322	
323	  submitTransaction(sub: TransactionSubmission, signatures: readonly Uint8Array[]): WalletTask {
324	    // 原始值透传，由 submit 统一做安全转换，避免在入口抛出原生 TypeError
325	    return this.submit(
326	      'transaction',
327	      {
328	        nonce: sub.nonce,
329	        deadline: sub.deadline,
330	        to: sub.to,
331	        value: sub.value,
332	        data: sub.data ?? new Uint8Array(),
333	      },
334	      signatures,
335	    );
336	  }
337	
338	  // ---------- 原子批量普通交易提交 ----------
339	
340	  /**
341	   * 提交一个有序调用列表作为单个原子批量任务。
342	   *
343	   * 摘要使用 safe-wallet/tx-batch/v1 域标签，绑定钱包标识、nonce、截止时间与按顺序编码的
344	   * 全部调用：单笔交易 / 策略变更 / 取消签名都不能授权批量交易；任一调用的收款方、金额、
345	   * data 或调用顺序、项数变化都会改变摘要。
346	   *
347	   * 校验顺序与单笔提交一致（任一失败都不建任务、不消费 nonce、不改策略/队列）：
348	   *   1) nonce 复用 → NonceAlreadyUsedError（旧请求重放恒得此异常，即使已过期）
349	   *   2) deadline 早于当前时间 → RequestExpired
350	   *   3) 列表（1..64 项）、收款地址、金额、data、nonce 顺序、阈值签名 → InvalidTransactionBatch
351	   *
352	   * 成功时只入队一个批量任务、只消费本次 nonce 并推进 expectedNonce。
353	   */
354	  submitBatchTransaction(sub: BatchTransactionSubmission, signatures: readonly Uint8Array[]): WalletTask {
355	    return this.submit(
356	      'transaction-batch',
357	      {
358	        nonce: sub.nonce,
359	        deadline: sub.deadline,
360	        calls: sub.calls,
361	      },
362	      signatures,
363	    );
364	  }
365	
366	  // ---------- 策略变更提交 ----------
367	
368	  proposePolicyChange(sub: PolicyChangeSubmission, signatures: readonly Uint8Array[]): WalletTask {
369	    return this.submit(
370	      'policy-change',
371	      {
372	        version: sub.version,
373	        nonce: sub.nonce,
374	        deadline: sub.deadline,
375	        newOwners: sub.newOwners,
376	        newConfirmations: sub.newConfirmations,
377	      },
378	      signatures,
379	    );
380	  }
381	
382	  // ---------- 任务取消 ----------
383	
384	  /**
385	   * 取消一个尚未执行的 queued 任务。
386	   *
387	   * 取消摘要使用 safe-wallet/cancel/v1 域标签，绑定钱包标识、目标任务 digest、nonce 与
388	   * 截止时间：签名无法改绑其他任务、其他钱包或其他时间窗口。
389	   *
390	   * 校验顺序（任一失败都不改变任务、不消费 nonce、不改变策略）：
391	   *   1) 字段非法 → InvalidCancellation
392	   *   2) nonce 复用 → NonceAlreadyUsedError（旧请求重放恒得此异常，即使已过期）
393	   *   3) deadline 早于当前时间 → RequestExpired
394	   *   4) nonce 顺序（须等于 expectedNonce）→ InvalidCancellation
395	   *   5) 目标不存在 → TaskNotFoundError；目标已终态 → TaskCancellationConflict
396	   *   6) 阈值签名（当前所有者、去重后达到当前确认数）→ InvalidCancellation
397	   *
398	   * 成功时目标任务由 queued 进入 cancelled 终态并返回：保留原 payload/digest/nonce，
399	   * 记录取消时间与取消摘要；不执行目标效果，不改变 owners/确认数/策略版本，
400	   * 只消费本次 nonce 并推进 expectedNonce。取消不要求任务在队首，也不调整队列顺序。
401	   */
402	  cancelTask(
403	    taskId: string,
404	    nonce: bigint | number,
405	    deadline: bigint | number,
406	    signatures: readonly Uint8Array[],
407	  ): WalletTask;
408	  cancelTask(sub: CancellationSubmission, signatures: readonly Uint8Array[]): WalletTask;
409	  cancelTask(
410	    a: string | CancellationSubmission,
411	    b: readonly Uint8Array[] | bigint | number,
412	    c?: bigint | number,
413	    d?: readonly Uint8Array[],
414	  ): WalletTask {
415	    const sub: CancellationSubmission =
416	      typeof a === 'string' || a === undefined || a === null
417	        ? { taskId: a as string, nonce: b as bigint | number, deadline: c as bigint | number }
418	        : a;
419	    const signatures: readonly Uint8Array[] =
420	      (typeof a === 'string' || a === undefined || a === null ? d : (b as readonly Uint8Array[])) ??
421	      ([] as readonly Uint8Array[]);
422	
423	    // (1) 字段安全转换（畸形输入只抛 InvalidCancellation）
424	    const nonce = toBigInt(sub.nonce, InvalidCancellation, 'nonce');
425	    if (!isNonNegativeInteger(nonce)) {
426	      throw new InvalidCancellation('nonce must be a non-negative integer');
427	    }
428	    // (2) nonce 复用优先于过期判定
429	    if (this.usedNonces.has(nonce)) throw new NonceAlreadyUsedError(nonce);
430	
431	    const deadline = toBigInt(sub.deadline, InvalidCancellation, 'deadline');
432	    if (!isNonNegativeInteger(deadline)) throw new InvalidCancellation('deadline out of range');
433	    // (3) 截止时间
434	    if (deadline < this.now()) {
435	      throw new RequestExpired(`request deadline ${deadline} already passed`);
436	    }
437	    // (4) nonce 顺序：取消与提交共用同一严格递增序列
438	    if (nonce !== this.nextNonce) {
439	      throw new InvalidCancellation(`expected nonce ${this.nextNonce}, got ${nonce}`);
440	    }
441	
442	    // (5) 目标任务状态
443	    const taskId = sub.taskId;
444	    if (typeof taskId !== 'string' || taskId.length === 0) {
445	      throw new InvalidCancellation('taskId must be a non-empty string');
446	    }
447	    const target = this.queue.getTask(taskId);
448	    if (target === null) throw new TaskNotFoundError(`task not found: ${taskId}`);
449	    if (target.status !== 'queued') {
450	      throw new TaskCancellationConflict(`task ${taskId} is already ${target.status}`);
451	    }
452	
453	    // (6) 阈值签名：摘要绑定钱包标识、目标任务 digest、nonce、deadline
454	    const digest = hashCancellation({
455	      walletId: this.id,
456	      taskDigest: target.digest,
457	      nonce,
458	      deadline,
459	    });
460	    this.verifyThresholdSignatures(digest, signatures, InvalidCancellation);
461	
462	    // 原子生效：目标任务进入 cancelled 终态 + 消费 nonce；策略与队列顺序不变
463	    const cancelled = this.queue.cancel(taskId, this.now(), digest.toString('hex'));
464	    this.usedNonces.add(nonce);
465	    this.nextNonce = nonce + 1n;
466	    return cancelled;
467	  }
468	
469	  // ---------- 普通交易分阶段审批（签名收集与提交分离；旧入口行为不变） ----------
470	
471	  /**
472	   * 创建一笔普通交易的分阶段审批：只校验并登记，不消费 nonce、不建任务、不改策略。
473	   *
474	   * 审批摘要用 safe-wallet/tx-approval/v1 域，绑定钱包标识、创建时策略版本与完整交易字段
475	   * （data 复制保存），与直接提交的 safe-wallet/tx/v1 摘要互不通用。
476	   *
477	   * 校验顺序与 submitTransaction 一致（失败不产生任何状态变化）：
478	   *   1) nonce 复用 → NonceAlreadyUsedError
479	   *   2) deadline 早于当前时间 → RequestExpired
480	   *   3) 字段非法或 nonce 跳号（须等于 expectedNonce）→ InvalidTransaction
481	   *
482	   * 成功时返回审批快照（标识、摘要、版本、确认数、空签名者列表、collecting 状态）。
483	   */
484	  createTransactionApproval(sub: TransactionSubmission): TransactionApproval {
485	    // (1) nonce 安全转换与复用判定（复用优先于过期，与既有提交一致）
486	    const nonce = toBigInt(sub.nonce, InvalidTransaction, 'nonce');
487	    if (!isNonNegativeInteger(nonce)) throw new InvalidTransaction('nonce must be a non-negative integer');
488	    if (this.usedNonces.has(nonce)) throw new NonceAlreadyUsedError(nonce);
489	
490	    // (2) 截止时间
491	    const deadline = toBigInt(sub.deadline, InvalidTransaction, 'deadline');
492	    if (!isNonNegativeInteger(deadline)) throw new InvalidTransaction('deadline out of range');
493	    if (deadline < this.now()) {
494	      throw new RequestExpired(`request deadline ${deadline} already passed`);
495	    }
496	    // (3) nonce 顺序：创建只登记不消费，但仍须绑定当前期望 nonce（跳号即非法）
497	    if (nonce !== this.nextNonce) {
498	      throw new InvalidTransaction(`expected nonce ${this.nextNonce}, got ${nonce}`);
499	    }
500	
501	    // (4) 交易字段校验与规范化（与直接提交同一套规则）
502	    const to = normalizeAddress(sub.to);
503	    if (to === null || isZeroAddress(to)) throw new InvalidTransaction('invalid or zero recipient address');
504	    const value = toBigInt(sub.value, InvalidTransaction, 'value');
505	    if (!isNonNegativeInteger(value)) throw new InvalidTransaction('value out of range');
506	    const dataField = sub.data;
507	    if (dataField !== undefined && !(dataField instanceof Uint8Array) && !ArrayBuffer.isView(dataField)) {
508	      throw new InvalidTransaction('data must be a byte array');
509	    }
510	    // 复制一份，避免创建后调用方改动同一缓冲区影响审批内容/摘要
511	    const data = Buffer.from((dataField as Uint8Array | undefined) ?? new Uint8Array());
512	
513	    const req: TransactionApprovalRequest = {
514	      walletId: this.id,
515	      version: this.version,
516	      nonce,
517	      deadline,
518	      to,
519	      value,
520	      data,
521	    };
522	    const digest = hashTransactionApproval(req);
523	    const id = createHash('sha256')
524	      .update(`approval:${this.approvalSeq}:${digest.toString('hex')}`)
525	      .digest('hex')
526	      .slice(0, 16);
527	    this.approvalSeq += 1;
528	
529	    const record: ApprovalRecord = {
530	      id,
531	      digest,
532	      version: this.version,
533	      confirmations: this.confirmations,
534	      nonce,
535	      deadline,
536	      to,
537	      value,
538	      data,
539	      signers: [],
540	      signatures: new Map(),
541	      submitted: false,
542	    };
543	    this.approvals.set(id, record);
544	    return this.approvalSnapshot(record);
545	  }
