547	  /**
548	   * 给审批追加一个 65 字节签名（每次一个）。
549	   *
550	   * 校验顺序：
551	   *   1) 审批不存在 → ApprovalNotFoundError
552	   *   2) 已提交 → ApprovalAlreadySubmittedError
553	   *   3) 已过期 → ApprovalExpiredError（过期优先于版本冲突）
554	   *   4) 策略版本漂移 → ApprovalPolicyConflictError
555	   *   5) 签名格式 / 与摘要不符 / 签名者非当前所有者 → InvalidApprovalSignatureError
556	   *   6) 同一所有者重复加签 → DuplicateApprovalSignatureError
557	   *
558	   * 达到创建时确认数后状态变为 ready；任一失败都不改变审批内容。
559	   */
560	  addApprovalSignature(approvalId: string, signature: Uint8Array): TransactionApproval {
561	    const record = this.getApprovalRecord(approvalId);
562	    this.assertApprovalActive(record);
563	
564	    if (!(signature instanceof Uint8Array) || signature.length !== 65) {
565	      throw new InvalidApprovalSignatureError('signature must be a 65-byte r||s||v blob');
566	    }
567	    const signer = recoverAddress(record.digest, Uint8Array.from(signature));
568	    if (signer === null) {
569	      throw new InvalidApprovalSignatureError('malformed or non-canonical signature');
570	    }
571	    if (!this.ownerSet.has(signer)) {
572	      throw new InvalidApprovalSignatureError('signature does not match approval or signer is not an owner');
573	    }
574	    if (record.signatures.has(signer)) {
575	      throw new DuplicateApprovalSignatureError(`owner already signed: ${signer}`);
576	    }
577	    record.signers.push(signer);
578	    record.signatures.set(signer, Buffer.from(signature));
579	    return this.approvalSnapshot(record);
580	  }
