587	  /**
588	   * 阈值满足后提交审批：按既有 safe-wallet/tx/v1 摘要入队一个普通交易任务，
589	   * 只消费创建时绑定的 nonce 并推进 expectedNonce；队列与既有终态行为不变。
590	   *
591	   * 校验顺序（任一失败都不消费 nonce、不建任务、不改策略）：
592	   *   1) 审批不存在 → ApprovalNotFoundError；已提交 → ApprovalAlreadySubmittedError
593	   *   2) 已过期 → ApprovalExpiredError；版本漂移 → ApprovalPolicyConflictError（过期优先）
594	   *   3) 签名不足创建时确认数 → ApprovalThresholdNotMetError
595	   *   4) nonce 已消费 → NonceAlreadyUsedError；nonce ≠ expectedNonce → ApprovalNonceConflictError
596	   */
597	  submitApprovedTransaction(approvalId: string): WalletTask {
598	    const record = this.getApprovalRecord(approvalId);
599	    this.assertApprovalActive(record);
600	
601	    if (BigInt(record.signers.length) < record.confirmations) {
602	      throw new ApprovalThresholdNotMetError(
603	        `threshold not met: need ${record.confirmations} distinct owners, got ${record.signers.length}`,
604	      );
605	    }
606	    if (this.usedNonces.has(record.nonce)) throw new NonceAlreadyUsedError(record.nonce);
607	    if (record.nonce !== this.nextNonce) {
608	      throw new ApprovalNonceConflictError(`expected nonce ${this.nextNonce}, got ${record.nonce}`);
609	    }
610	
611	    // 按既有普通交易摘要入队（与 submitTransaction 同一域、同一载荷形状）
612	    const req: TransactionRequest = {
613	      walletId: this.id,
614	      nonce: record.nonce,
615	      deadline: record.deadline,
616	      to: record.to,
617	      value: record.value,
618	      data: record.data,
619	    };
620	    const digest = hashTransaction(req);
621	    const payload: WalletTaskPayload = {
622	      kind: 'transaction',
623	      deadline: record.deadline,
624	      to: record.to,
625	      value: record.value,
626	      data: Buffer.from(record.data),
627	    };
628	    let task: WalletTask;
629	    try {
630	      task = this.queue.enqueue({
631	        nonce: record.nonce,
632	        digest: digest.toString('hex'),
633	        payload,
634	        submittedAt: this.now(),
635	      });
636	    } catch (err) {
637	      if (err instanceof InvalidQueueStateError) throw new InvalidTransaction(err.message);
638	      throw err;
639	    }
640	    // 原子生效：入队 + 消费 nonce + 审批进入 submitted 终态
641	    this.usedNonces.add(record.nonce);
642	    this.nextNonce = record.nonce + 1n;
643	    record.submitted = true;
644	    return task;
645	  }
