846	  /**
847	   * 统一提交入口。raw 接收未经转换的原始标量（bigint/number/string），
848	   * 所有转换与字段合法性判定都在这里完成，保证只能抛出约定错误类型。
849	   */
850	  private submit(
851	    kind: WalletTaskPayload['kind'],
852	    raw: Record<string, unknown>,
853	    signatures: readonly Uint8Array[],
854	  ): WalletTask {
855	    const Invalid =
856	      kind === 'policy-change'
857	        ? InvalidPolicyChange
858	        : kind === 'transaction-batch'
859	          ? InvalidTransactionBatch
860	          : InvalidTransaction;
861	
862	    // 校验优先级（任一失败都不建任务、不消费 nonce、不改策略）：
863	    //   1) nonce 复用 → 既有重放防护的公开异常（旧请求重放即使已过期也仍报复用）
864	    //   2) 截止时间早于当前时间 → RequestExpired
865	    //   3) 字段 / 版本 / nonce 顺序 / 签名 → 对应 Invalid*
866	    const nonce = toBigInt(raw.nonce, Invalid, 'nonce');
867	    if (!isNonNegativeInteger(nonce)) throw new Invalid('nonce must be a non-negative integer');
868	    if (this.usedNonces.has(nonce)) throw new NonceAlreadyUsedError(nonce);
869	
870	    const deadline = toBigInt(raw.deadline, Invalid, 'deadline');
871	    if (!isNonNegativeInteger(deadline)) throw new Invalid('deadline out of range');
872	    if (deadline < this.now()) {
873	      throw new RequestExpired(`request deadline ${deadline} already passed`);
874	    }
875	    if (nonce !== this.nextNonce) throw new Invalid(`expected nonce ${this.nextNonce}, got ${nonce}`);
876	
877	    // (3) 字段校验 + 规范化
878	    let payload: WalletTaskPayload;
879	    let digest: Buffer;
880	    if (kind === 'transaction') {
881	      const to = normalizeAddress(raw.to as string);
882	      if (to === null || isZeroAddress(to)) throw new Invalid('invalid or zero recipient address');
883	      const value = toBigInt(raw.value, Invalid, 'value');
884	      if (!isNonNegativeInteger(value)) throw new Invalid('value out of range');
885	      const dataField = raw.data;
886	      if (
887	        dataField !== undefined &&
888	        !(dataField instanceof Uint8Array) &&
889	        !ArrayBuffer.isView(dataField)
890	      ) {
891	        throw new Invalid('data must be a byte array');
892	      }
893	      const data = Buffer.from((dataField as Uint8Array | undefined) ?? new Uint8Array());
894	      const req: TransactionRequest = {
895	        walletId: this.id,
896	        nonce,
897	        deadline,
898	        to,
899	        value,
900	        data,
901	      };
902	      digest = hashTransaction(req);
903	      payload = { kind: 'transaction', deadline, to, value, data };
904	    } else if (kind === 'transaction-batch') {
905	      // 有序调用列表：1..64 项；逐项规范化收款地址、金额与 data（顺序保持不变）
906	      const calls = this.normalizeBatchCalls(raw.calls);
907	      const req: TransactionBatchRequest = {
908	        walletId: this.id,
909	        nonce,
910	        deadline,
911	        calls,
912	      };
913	      digest = hashTransactionBatch(req);
914	      payload = { kind: 'transaction-batch', deadline, calls };
915	    } else {
916	      // (3) 版本与目标策略字段（直接提交与分阶段审批共用同一套规则）
917	      const { version, newOwners, newConfirmations } = this.normalizePolicyChangeFields(raw);
918	      const req: PolicyChangeRequest = {
919	        walletId: this.id,
920	        version,
921	        nonce,
922	        deadline,
923	        newOwners,
924	        newConfirmations,
925	      };
926	      digest = hashPolicyChange(req);
927	      payload = { kind: 'policy-change', deadline, version, newOwners, newConfirmations };
928	    }
929	
930	    // (4) 阈值签名：恢复 → 去重 → 必须为当前所有者 → 数量达到当前确认数
931	    this.verifyThresholdSignatures(digest, signatures, Invalid);
932	
933	    // (5) 原子生效（到队列为止）：入队 + 消费 nonce。
934	    //     入队失败（同一摘要重复等）时不消费 nonce。
935	    let task: WalletTask;
936	    try {
937	      task = this.queue.enqueue({
938	        nonce,
939	        digest: digest.toString('hex'),
940	        payload,
941	        submittedAt: this.now(),
942	      });
943	    } catch (err) {
944	      if (err instanceof InvalidQueueStateError) throw new Invalid(err.message);
945	      throw err;
946	    }
947	    this.usedNonces.add(nonce);
948	    this.nextNonce = nonce + 1n;
949	    return task;
950	  }
951	
952	  /**
953	   * 规范化批量调用列表：必须是 1..MAX_BATCH_CALLS 项的数组，每项是对象，
954	   * 收款地址合法且非零、金额为 256 位以内非负整数、data 必须是 Uint8Array。
955	   * 保持输入顺序；任何畸形都归为 InvalidTransactionBatch。
956	   */
957	  private normalizeBatchCalls(rawCalls: unknown): BatchCall[] {
958	    if (!Array.isArray(rawCalls) || rawCalls.length === 0) {
959	      throw new InvalidTransactionBatch('calls must be a non-empty array');
960	    }
961	    if (rawCalls.length > MAX_BATCH_CALLS) {
962	      throw new InvalidTransactionBatch(`too many calls: ${rawCalls.length} > ${MAX_BATCH_CALLS}`);
963	    }
964	    const calls: BatchCall[] = [];
965	    for (const rawCall of rawCalls) {
966	      if (typeof rawCall !== 'object' || rawCall === null) {
967	        throw new InvalidTransactionBatch('each batch call must be an object');
968	      }
969	      const call = rawCall as Record<string, unknown>;
970	      const to = normalizeAddress(call.to as string);
971	      if (to === null || isZeroAddress(to)) {
972	        throw new InvalidTransactionBatch('invalid or zero recipient address in batch call');
973	      }
974	      const value = toBigInt(call.value, InvalidTransactionBatch, 'value');
975	      if (!isNonNegativeInteger(value)) {
976	        throw new InvalidTransactionBatch('batch call value out of range');
977	      }
978	      if (!(call.data instanceof Uint8Array)) {
979	        throw new InvalidTransactionBatch('batch call data must be a Uint8Array');
980	      }
981	      // 复制一份，避免入队后调用方再改动同一缓冲区影响任务内容/摘要
982	      calls.push({ to, value, data: Buffer.from(call.data) });
983	    }
984	    return calls;
985	  }
986	
987	  /**
988	   * 规范化策略变更字段（直接提交 proposePolicyChange 与分阶段审批 createPolicyApproval 共用）：
989	   *   - 版本必须绑定当前版本（提交/创建时不匹配 → InvalidPolicyChange；执行时漂移 → PolicyConflict）
990	   *   - 新所有者列表非空、无重复、无零地址、全部合法（保持输入顺序）
991	   *   - 新确认数大于 0 且不超过新所有者数量
992	   * 任一不合法都抛 InvalidPolicyChange；成功返回规范化后的值。
993	   */
994	  private normalizePolicyChangeFields(raw: Record<string, unknown>): {
995	    version: bigint;
996	    newOwners: Address[];
997	    newConfirmations: bigint;
998	  } {
999	    const version = toBigInt(raw.version, InvalidPolicyChange, 'version');
1000	    if (version !== this.version) {
1001	      throw new InvalidPolicyChange(
1002	        `policy version mismatch: bound ${version}, current ${this.version}`,
1003	      );
1004	    }
1005	    const newOwners = normalizeOwnerList(raw.newOwners as string[], InvalidPolicyChange);
1006	    const newConfirmations = toBigInt(raw.newConfirmations, InvalidPolicyChange, 'newConfirmations');
1007	    if (newConfirmations <= 0n || newConfirmations > BigInt(newOwners.length)) {
1008	      throw new InvalidPolicyChange(
1009	        `new confirmations must be within 1..new owners (${newOwners.length}), got ${newConfirmations}`,
1010	      );
1011	    }
1012	    return { version, newOwners, newConfirmations };
1013	  }
1014	
1015	  // ---------- 分阶段审批内部辅助 ----------
1016	
1017	  private getApprovalRecord(approvalId: string): ApprovalRecord {
1018	    const record = typeof approvalId === 'string' ? this.approvals.get(approvalId) : undefined;
1019	    if (record === undefined) throw new ApprovalNotFoundError(`approval not found: ${String(approvalId)}`);
1020	    return record;
1021	  }
1022	
1023	  /** 已提交 / 已过期 / 版本漂移的审批不可再加签或提交（过期优先于版本冲突） */
1024	  private assertApprovalActive(record: ApprovalRecord): void {
1025	    if (record.submitted) throw new ApprovalAlreadySubmittedError(`approval ${record.id} already submitted`);
1026	    if (record.deadline < this.now()) {
1027	      throw new ApprovalExpiredError(`approval deadline ${record.deadline} already passed`);
1028	    }
1029	    if (record.version !== this.version) {
1030	      throw new ApprovalPolicyConflictError(
1031	        `policy version drifted: approval bound ${record.version}, current ${this.version}`,
1032	      );
1033	    }
1034	  }
1035	
1036	  /** 派生状态：submitted > expired > conflicted > ready > collecting */
1037	  private approvalStatus(record: ApprovalRecord): ApprovalStatus {
1038	    if (record.submitted) return 'submitted';
1039	    if (record.deadline < this.now()) return 'expired';
1040	    if (record.version !== this.version) return 'conflicted';
1041	    return BigInt(record.signers.length) >= record.confirmations ? 'ready' : 'collecting';
1042	  }
1043	
1044	  private approvalSnapshot(record: ApprovalRecord): TransactionApproval {
1045	    return {
1046	      id: record.id,
1047	      digest: record.digest.toString('hex'),
1048	      version: record.version,
1049	      confirmations: record.confirmations,
1050	      signers: [...record.signers],
1051	      status: this.approvalStatus(record),
1052	    };
1053	  }
1054	
1055	  // ---------- 策略变更分阶段审批内部辅助 ----------
1056	
1057	  private getPolicyApprovalRecord(approvalId: string): PolicyApprovalRecord {
1058	    const record =
1059	      typeof approvalId === 'string' ? this.policyApprovals.get(approvalId) : undefined;
1060	    if (record === undefined) {
1061	      throw new ApprovalNotFoundError(`policy approval not found: ${String(approvalId)}`);
1062	    }
1063	    return record;
1064	  }
1065	
1066	  /** 已提交 / 已过期 / 版本漂移的策略审批不可再加签或提交（过期优先于版本冲突） */
1067	  private assertPolicyApprovalActive(record: PolicyApprovalRecord): void {
1068	    if (record.submitted) {
1069	      throw new ApprovalAlreadySubmittedError(`policy approval ${record.id} already submitted`);
1070	    }
1071	    if (record.deadline < this.now()) {
1072	      throw new ApprovalExpiredError(`policy approval deadline ${record.deadline} already passed`);
1073	    }
1074	    if (record.version !== this.version) {
1075	      throw new ApprovalPolicyConflictError(
1076	        `policy version drifted: approval bound ${record.version}, current ${this.version}`,
1077	      );
1078	    }
1079	  }
1080	
1081	  /** 派生状态：submitted > expired > conflicted > ready > collecting（与普通交易审批同一序） */
1082	  private policyApprovalStatus(record: PolicyApprovalRecord): ApprovalStatus {
1083	    if (record.submitted) return 'submitted';
1084	    if (record.deadline < this.now()) return 'expired';
1085	    if (record.version !== this.version) return 'conflicted';
1086	    return BigInt(record.signers.length) >= record.confirmations ? 'ready' : 'collecting';
1087	  }
1088	
1089	  private policyApprovalSnapshot(record: PolicyApprovalRecord): PolicyApproval {
1090	    return {
1091	      id: record.id,
1092	      digest: record.digest.toString('hex'),
1093	      version: record.version,
1094	      confirmations: record.confirmations,
1095	      nonce: record.nonce,
1096	      deadline: record.deadline,
1097	      newOwners: [...record.newOwners],
1098	      newConfirmations: record.newConfirmations,
1099	      signers: [...record.signers],
1100	      status: this.policyApprovalStatus(record),
1101	    };
1102	  }
1103	
1104	  /** 按“当前策略”的所有者集合与确认数校验签名收集 */
1105	  private verifyThresholdSignatures(
1106	    digest: Uint8Array,
1107	    signatures: readonly Uint8Array[],
1108	    Invalid: new (msg: string) => Error,
1109	  ): void {
1110	    if (!Array.isArray(signatures)) {
1111	      throw new Invalid('signatures must be an array');
1112	    }
1113	    if (signatures.length === 0) throw new Invalid('missing signatures');
1114	
1115	    const signedBy = new Set<Address>();
1116	    for (const sig of signatures) {
1117	      if (!(sig instanceof Uint8Array) || sig.length !== 65) {
1118	        throw new Invalid('each signature must be a 65-byte r||s||v blob');
1119	      }
1120	      const signer = recoverAddress(digest, Uint8Array.from(sig));
1121	      if (signer === null) throw new Invalid('malformed or non-canonical signature');
1122	      if (!this.ownerSet.has(signer)) {
1123	        // 非所有者签名：既可能是伪造，也可能是签名载荷与提交内容不匹配
1124	        throw new Invalid('signature does not match payload or signer is not an owner');
1125	      }
1126	      signedBy.add(signer); // 地址去重：同一所有者多签只计一次
1127	    }
1128	    if (BigInt(signedBy.size) < this.confirmations) {
1129	      throw new Invalid(
1130	        `threshold not met: need ${this.confirmations} distinct owners, got ${signedBy.size}`,
1131	      );
1132	    }
1133	  }
1134	
1135	  /** 队列执行器回调：定义各类任务的生效语义 */
1136	  private applyTask(task: WalletTask): unknown {
1137	    const p = task.payload;
1138	    if (p.kind === 'transaction') {
1139	      // 普通交易既有执行结果：一个可观察的执行产物；不触碰策略状态。
1140	      // 截止时间只在提交阶段核对（RequestExpired），不作为执行闸门，以保持既有执行结果不变。
1141	      return {
1142	        kind: 'transfer',
1143	        to: p.to,
1144	        value: p.value,
1145	        data: Buffer.from(p.data).toString('hex'),
1146	      };
1147	    }
1148	
1149	    if (p.kind === 'transaction-batch') {
1150	      // 原子批量：执行器一次性产出整批回执。调用方（队列）在本回调正常返回后才写入
1151	      // executed 终态；本回调抛出则整批进入 failed，不产生部分执行回执。
1152	      // 截止时间同样不是执行闸门，与单笔普通交易保持一致。
1153	      return {
1154	        kind: 'transfer-batch',
1155	        calls: p.calls.map((call) => ({
1156	          to: call.to,
1157	          value: call.value,
1158	          data: Buffer.from(call.data).toString('hex'),
1159	        })),
1160	      };
1161	    }
1162	
1163	    // 策略变更：仅当绑定版本仍等于当前版本时生效
1164	    if (p.version !== this.version) {
1165	      throw new PolicyConflict(
1166	        `policy version drifted: task bound ${p.version}, current ${this.version}`,
1167	      );
1168	    }
1169	    // 所有者集合与确认数同时替换；版本恰好递增一次
1170	    this.owners = [...p.newOwners];
1171	    this.ownerSet.clear();
1172	    for (const o of this.owners) this.ownerSet.add(o);
1173	    this.confirmations = p.newConfirmations;
1174	    this.version += 1n;
1175	    return {
1176	      kind: 'policy-applied',
1177	      version: this.version,
1178	      owners: [...this.owners],
1179	      confirmations: this.confirmations,
1180	    };
1181	  }
1182	}
1183	
1184	// ---------- 所有者列表规范化（空/重复/零地址校验） ----------
1185	
1186	function normalizeOwnerList(
1187	  input: readonly string[],
1188	  ErrorCtor: typeof InvalidPolicyChange | typeof InvalidTransaction = InvalidPolicyChange,
1189	): Address[] {
1190	  if (!Array.isArray(input) || input.length === 0) {
1191	    throw new ErrorCtor('owners list must be a non-empty array');
1192	  }
1193	  const out: Address[] = [];
1194	  const seen = new Set<Address>();
1195	  for (const raw of input) {
1196	    const addr = normalizeAddress(raw);
1197	    if (addr === null) throw new ErrorCtor(`invalid owner address: ${String(raw)}`);
1198	    if (addr === ZERO_ADDRESS || isZeroAddress(addr)) {
1199	      throw new ErrorCtor('zero address is not allowed as owner');
1200	    }
1201	    if (seen.has(addr)) throw new ErrorCtor(`duplicate owner: ${addr}`);
1202	    seen.add(addr);
1203	    out.push(addr);
1204	  }
1205	  return out;
1206	}
1207

