export function hashTransaction(req: {
  walletId: string;
  nonce: bigint | number;
  deadline: bigint | number;
  to: Address;
  value: bigint | number;
  data: Uint8Array;
}): Buffer {
  return digest(TAG_TX, [
    encBytes(walletIdBytes(req.walletId)),
    encUint(req.nonce),
    encUint(deadlineToBigint(req.deadline)),
    encBytes(hexToBytes(req.to)),
    encUint(req.value),
    encBytes(req.data),
  ]);
}

